package com.smartlostfound.ui;

import com.smartlostfound.dao.*;
import com.smartlostfound.model.*;
import java.sql.SQLException;
import java.util.*;

public class AdminMenu extends RoleMenu {
    private final ActivityLogDao logDao=new ActivityLogDao();
    public AdminMenu(User user,UserDao dao,Scanner scanner){super(user,dao,scanner);}
    protected String title(){return "ADMIN MENU";} protected Role requiredRole(){return Role.ADMIN;}
    protected String[] options(){return new String[]{"View All System Users","View Pending Registrations","Approve User Account","Update User Role & Status","View System Audit Logs","Filter Audit Logs by User ID","Clear Historical Audit Logs","View All Found-Item Records","Delete Found-Item Record"};}
    protected void handleOption(int n){try{switch(n){case 1->printUsers(userDao.getAllUsers());case 2->printUsers(userDao.getPendingUsers());case 3->approve();case 4->updateUser();case 5->printLogs(logDao.getAllLogs());case 6->filterLogs();case 7->clearLogs();case 8->printItems(itemDao.getAll());case 9->deleteItem();default->System.out.println("Invalid choice.");}}catch(SQLException|IllegalArgumentException e){System.out.println("Operation failed: "+e.getMessage());}}
    private void approve()throws SQLException{printUsers(userDao.getPendingUsers());int id=readPositiveInt("User ID to approve: ");System.out.println(userDao.approveUser(id,user.id())?"Account approved and audit entry saved.":"No pending account found with that ID.");}
    private void updateUser()throws SQLException{printUsers(userDao.getAllUsers());int id=readPositiveInt("Target user ID (0 to cancel): ");if(id==0)return;if(id==user.id()){System.out.println("You cannot modify your active administrator account here.");return;}String role=readRequired("New role (ADMIN/FINDER/OWNER): ").toUpperCase(Locale.ROOT),status=readRequired("New status (APPROVED/PENDING/REJECTED): ").toUpperCase(Locale.ROOT);if(!Set.of("ADMIN","FINDER","OWNER").contains(role)||!Set.of("APPROVED","PENDING","REJECTED").contains(status)){System.out.println("Invalid role or status.");return;}System.out.println(userDao.updateUserRoleAndStatus(id,role,status,user.id())?"User updated and audit entry saved.":"User ID not found.");}
    private void filterLogs()throws SQLException{int id=readPositiveInt("User ID to filter: ");printLogs(logDao.getLogsByUserId(id));}
    private void clearLogs()throws SQLException{System.out.print("This permanently deletes all historical audit rows. Type CLEAR ALL to continue: ");if(!scanner.nextLine().trim().equals("CLEAR ALL")){System.out.println("Clear cancelled.");return;}int count=logDao.clearAllLogs();logDao.logAction(user.id(),"AUDIT_LOGS_CLEARED","Admin cleared "+count+" historical audit log row(s); this action is retained as a new audit entry.");System.out.println(count+" historical log(s) cleared. The clear operation itself was logged.");}
    private void deleteItem()throws SQLException{printItems(itemDao.getAll());int id=readPositiveInt("Found-item ID to delete: ");System.out.print("Permanently delete this item record? (YES/NO): ");if(scanner.nextLine().trim().equalsIgnoreCase("YES"))System.out.println(itemDao.adminDelete(id,user.id())?"Item deleted and audit entry saved.":"Item record not found.");else System.out.println("Delete cancelled.");}
    private void printUsers(List<User> users){if(users.isEmpty()){System.out.println("No users to display.");return;}System.out.printf("%-5s | %-22s | %-10s | %-10s%n","ID","USERNAME","ROLE","STATUS");System.out.println("--------------------------------------------------------");for(User u:users)System.out.printf("%-5d | %-22.22s | %-10s | %-10s%n",u.id(),u.username(),u.roles(),u.status());}
    private void printLogs(List<ActivityLog> logs){if(logs.isEmpty()){System.out.println("No audit logs found.");return;}System.out.printf("%-5s | %-5s | %-18s | %-35s | %-50s | %-23s%n","ID","UID","USERNAME","ACTION","DESCRIPTION","TIMESTAMP");System.out.println("-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------");for(ActivityLog l:logs)System.out.printf("%-5d | %-5s | %-18.18s | %-35.35s | %-50.50s | %-23s%n",l.id(),l.userId()==null?"-":l.userId(),l.username(),l.actionType(),l.description(),l.timestamp());System.out.println("Total logs: "+logs.size());}
}
